## Code Example
```javascript
const { trace, context, propagation } = require('@opentelemetry/api');
const { NodeTracerProvider } = require('@opentelemetry/sdk-trace-node');
const { SimpleSpanProcessor } = require('@opentelemetry/sdk-trace-base');
const { OTLPTraceExporter } = require('@opentelemetry/exporter-otlp-http');

const provider = new NodeTracerProvider();
const exporter = new OTLPTraceExporter({ url: 'https://<region>.monitor.azure.com/v1/traces' });
provider.addSpanProcessor(new SimpleSpanProcessor(exporter));
provider.register();

module.exports = async function (context, req) {
  const tracer = trace.getTracer('example-function');
  const span = tracer.startSpan('http-request');
  // downstream calls propagate context automatically when using OpenTelemetry API
  span.end();
  return { status: 200, body: 'OK' };
};
```

